use crate::cross_chain::rlp_decoder::{Blockchain, RlpDecoder};
use ethnum::U256;

#[test]
fn test_decode_cross_chain_data() {
    let encoded_quote = "";

    let quote = RlpDecoder::decode_cross_chain_data(encoded_quote).unwrap();

    println!("{quote:?}");

    assert_eq!(
        quote.total_amount_in,
        U256::from_str_radix("50000000000000000000", 10).unwrap()
    );
    assert_eq!(
        quote.total_amount_out,
        U256::from_str_radix("11670858301863654", 10).unwrap()
    );
    assert_eq!(
        quote.total_min_amount_out.unwrap(),
        U256::from_str_radix("11577491435448744", 10).unwrap()
    );
    assert_eq!(quote.total_slippage.unwrap(), "0.8%");
    assert_eq!(quote.steps.len(), 3);

    let step1 = &quote.steps[0];
    assert_eq!(step1.chain_id, Blockchain::Evm(56));
    assert_eq!(
        step1.amount_in,
        U256::from_str_radix("50000000000000000000", 10).unwrap()
    );
    assert_eq!(step1.route.len(), 0);

    let has_routing = quote.steps.iter().any(|step| !step.route.is_empty());
    let has_qswap = quote.steps.iter().any(|step| step.qswap_data.is_some());
    assert!(has_routing || has_qswap);
}

#[test]
fn test_evm_to_evm_single_hop() {
    let quote = RlpDecoder::decode_cross_chain_data(
        "",
    ).unwrap();

    assert!(quote.total_amount_in > U256::ZERO);
    assert!(!quote.steps.is_empty());

    let has_evm_chain = quote
        .steps
        .iter()
        .any(|step| step.chain_id.to_id().to_string().len() <= 5);

    assert!(has_evm_chain)
}

#[test]
fn test_evm_to_evm_multi_hop() {
    let quote = RlpDecoder::decode_cross_chain_data(
        "",
    ).unwrap();

    assert!(!quote.steps.is_empty());
}

#[test]
fn test_evm_to_icp() {
    let quote = RlpDecoder::decode_cross_chain_data(
        "",
    ).unwrap();

    print!("{quote:?}");

    assert!(!quote.steps.is_empty());

    let has_bsc = quote
        .steps
        .iter()
        .any(|step| step.chain_id.to_id() == 56_u64);
    let has_icp = quote
        .steps
        .iter()
        .any(|step| step.chain_id.to_id() == 0_u64);

    assert!(quote.steps.len() == 2);

    assert!(
        has_bsc || has_icp,
        "Should have recognizable chain identifiers"
    );
}

#[test]
fn test_icp_to_evm() {
    let encoded_quote = "";

    let quote = RlpDecoder::decode_cross_chain_data(encoded_quote).unwrap();

    assert!(quote.total_amount_in > U256::ZERO);
    assert!(!quote.steps.is_empty());

    assert!(quote
        .steps
        .iter()
        .all(|step| step.chain_id.to_id() == 0_u64 || step.chain_id.to_id() == 56_u64));
}

#[test]
fn test_chain_id_validation() {
    let valid_chains = vec![
        "1", "56", "137", "8453", "42161", "10", "43114", "250", "icp",
    ];

    for chain_id in valid_chains {
        let is_supported = RlpDecoder::get_supported_chains()
            .contains_key(&Blockchain::Evm(chain_id.parse::<u64>().unwrap()));
        assert!(is_supported, "Chain {chain_id} should be supported");
    }

    let invalid_chains = vec!["999", "invalid", "", "0x1"];
    for chain_id in invalid_chains {
        if let Ok(id) = &chain_id.parse::<u64>() {
            let is_supported =
                RlpDecoder::get_supported_chains().contains_key(&Blockchain::Evm(*id));
            assert!(!is_supported, "Chain {chain_id} should not be supported");
        };
    }
}

#[test]
fn test_quote_size_limits() {
    let large_quote = hex::encode(vec![0u8; 2 * 1024 * 1024]);
    let result = RlpDecoder::decode_cross_chain_data(&large_quote);

    match result {
        Err(e) => assert!(e.to_string().contains("exceeds maximum size")),
        Ok(_quote) => {
            panic!("Should fail");
        }
    }
}

#[test]
fn test_invalid_rlp_quote() {
    let invalid_quote = hex::encode(vec![0x01, 0x02, 0x03, 0xff, 0xee]);
    let result = RlpDecoder::decode_cross_chain_data(&invalid_quote);

    assert!(result.is_err());
}

