#[test]
fn test_comprehensive_error_scenarios() {
    let error_cases = vec![vec![0xff], vec![0xc0], hex::decode("c1ff").unwrap()];

    for invalid_quote in error_cases {
        let result = RlpDecoder::decode_cross_chain_data(&hex::encode(&invalid_quote));

        assert!(result.is_err());
    }
}

