#[cfg(test)]
mod bench {
    use super::*;
    use std::time::Instant;

    #[test]
    fn test_decode_performance() {
        let test_quote = "";

        let iterations = 1000;
        let start = Instant::now();

        for _ in 0..iterations {
            let _ = RlpDecoder::decode_cross_chain_data(test_quote);
        }

        let duration = start.elapsed();
        let avg_time = duration / iterations;

        println!("Average decode time: {avg_time:?}");
        assert!(avg_time.as_micros() < 10000);
    }
}

#[test]
fn test_routing_validation_complex() {
    let complex_routing_quote = "";

    let quote = RlpDecoder::decode_cross_chain_data(complex_routing_quote).unwrap();
    for step in &quote.steps {
        for route in &step.route {
            assert!(!route.sell_token.is_empty());
            assert!(!route.buy_token.is_empty());
        }
    }
}

