#[test]
fn test_invalid_token_formats() {
    let invalid_tokens = vec![
        "0x123",
        "not_an_address",
        "0xZZZZ567890123456789012345678901234567890",
        "",
    ];

    for token in invalid_tokens {
        let token_bytes = token.as_bytes();
        let mut quote = vec![0xc0 + token_bytes.len() as u8];
        quote.extend_from_slice(token_bytes);

        let result = RlpDecoder::decode_cross_chain_data(&hex::encode(quote));

        assert!(result.is_err())
    }
}
